from pathlib import Path
from datetime import datetime,timezone
import json,re,hashlib
p=Path('docs/ai-records/manifest.json'); manifest=json.loads(p.read_text(encoding='utf-8')); root=Path.home()/'.codex'/'sessions'
for entry in manifest['sessions']:
    source=next(root.rglob(Path(entry['file']).name))
    lines=source.read_text(encoding='utf-8').splitlines(); selected=[]; omitted={}
    for n,line in enumerate(lines,1):
        try: obj=json.loads(line)
        except json.JSONDecodeError: continue
        kind=obj.get('type'); payload=obj.get('payload',{}); keep=False
        if kind=='response_item':
            typ=payload.get('type')
            keep=(payload.get('role') in ('user','assistant','tool') and payload.get('channel')!='analysis') if typ=='message' else typ in ('function_call','function_call_output','custom_tool_call','custom_tool_call_output','web_search_call')
        elif kind=='event_msg': keep=payload.get('type') in ('user_message','agent_message')
        if not keep:
            key=str(kind)+':'+str(payload.get('type','metadata')); omitted[key]=omitted.get(key,0)+1;continue
        raw=json.dumps(obj,ensure_ascii=False)
        raw=re.sub(r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}','[REDACTED_EMAIL]',raw)
        raw=re.sub(r'(?<!\w)sk-[A-Za-z0-9_-]{20,}','[REDACTED_KEY]',raw)
        selected.append(json.dumps({'source_line':n,'record':json.loads(raw)},ensure_ascii=False))
    target=Path(entry['file']);target.write_text('\n'.join(selected)+'\n',encoding='utf-8',newline='\n')
    entry.update(source_lines=len(lines),exported_records=len(selected),omitted_categories=omitted,sha256=hashlib.sha256(target.read_bytes()).hexdigest())
manifest['snapshot_utc']=datetime.now(timezone.utc).isoformat()
p.write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8',newline='\n')
print('snapshot_utc=',manifest['snapshot_utc'])
